<?php
require_once __DIR__.'/bakery_auth.php';$db=bakeryDbOrFail();$bakeryAccount=requireBakerySession($db);$error='';$success=['added'=>'Đã thêm nguyên liệu.','updated'=>'Đã cập nhật nguyên liệu.','toggled'=>'Đã đổi trạng thái nguyên liệu.','deleted'=>'Đã xóa nguyên liệu.'][$_GET['success']??'']??'';$form=['id'=>0,'name'=>'','unit'=>'kg','minimum_stock'=>'0','note'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_require($_POST['csrf_token']??'');$a=$_POST['action']??'';if($a==='delete'){$id=(int)($_POST['id']??0);$s=$db->prepare('SELECT COUNT(*) total FROM bakery_stock_movements WHERE material_id=?');$s->bind_param('i',$id);$s->execute();$used=(int)$s->get_result()->fetch_assoc()['total'];if($id<1)$error='Nguyên liệu không hợp lệ.';elseif($used>0)$error='Không thể xóa nguyên liệu đã có lịch sử nhập hoặc xuất kho. Hãy chọn “Ngừng” để giữ đúng báo cáo.';else try{$s=$db->prepare('DELETE FROM bakery_materials WHERE id=?');$s->bind_param('i',$id);$s->execute();header('Location: bakery_materials.php?success=deleted');exit;}catch(Throwable $e){$error='Không thể xóa nguyên liệu này.';}}if($a==='toggle'){$id=(int)$_POST['id'];$s=$db->prepare('UPDATE bakery_materials SET is_active=1-is_active WHERE id=?');$s->bind_param('i',$id);$s->execute();header('Location: bakery_materials.php?success=toggled');exit;}if($a==='save'){$form=['id'=>(int)($_POST['id']??0),'name'=>trim((string)($_POST['name']??'')),'unit'=>trim((string)($_POST['unit']??'')),'minimum_stock'=>trim((string)($_POST['minimum_stock']??'0')),'note'=>trim((string)($_POST['note']??''))];$minimum=str_replace(',','.',$form['minimum_stock']);if($minimum==='')$minimum='0';if($form['name']===''||mb_strlen($form['name'],'UTF-8')>150)$error='Tên nguyên liệu không hợp lệ.';elseif($form['unit']===''||mb_strlen($form['unit'],'UTF-8')>30)$error='Đơn vị không hợp lệ.';elseif(!preg_match('/^\d{1,10}(?:\.\d{1,3})?$/D',$minimum))$error='Mức tồn tối thiểu không hợp lệ.';else try{$id=(int)$form['id'];if($id){$s=$db->prepare('UPDATE bakery_materials SET name=?,unit=?,minimum_stock=?,note=? WHERE id=?');$s->bind_param('ssssi',$form['name'],$form['unit'],$minimum,$form['note'],$id);$ok='updated';}else{$s=$db->prepare('INSERT INTO bakery_materials(name,unit,minimum_stock,note) VALUES(?,?,?,?)');$s->bind_param('ssss',$form['name'],$form['unit'],$minimum,$form['note']);$ok='added';}$s->execute();header('Location: bakery_materials.php?success='.$ok);exit;}catch(Throwable $e){$error=(int)$e->getCode()===1062?'Tên nguyên liệu đã tồn tại.':'Không thể lưu nguyên liệu.';}}}
if($_SERVER['REQUEST_METHOD']!=='POST'&&isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$db->prepare('SELECT * FROM bakery_materials WHERE id=?');$s->bind_param('i',$id);$s->execute();if($r=$s->get_result()->fetch_assoc())$form=$r;}
$rows=$db->query("SELECT m.*,COALESCE(s.stock,0) AS stock FROM bakery_materials m LEFT JOIN (SELECT material_id,SUM(CASE WHEN movement_type IN ('purchase','adjustment_in') THEN quantity ELSE -quantity END) AS stock FROM bakery_stock_movements GROUP BY material_id) s ON s.material_id=m.id ORDER BY m.is_active DESC,m.name")->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Danh mục nguyên liệu</title></head><body><?php require __DIR__.'/bakery_nav.php';?><main class="bk-shell"><header class="bk-header"><div><h1>Danh mục nguyên vật liệu</h1><p>Khai báo nguyên liệu, đơn vị tính và mức cảnh báo tồn kho.</p></div></header><?php if($error):?><div class="bk-alert bk-alert-error"><?=bakeryH($error)?></div><?php endif;?><?php if($success):?><div class="bk-alert bk-alert-success"><?=bakeryH($success)?></div><?php endif;?><div class="bk-grid bk-grid-2"><section class="bk-card"><h2 class="bk-card-title"><?=$form['id']?'Sửa nguyên liệu':'Thêm nguyên liệu'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)$form['id']?>"><label class="bk-label">Tên nguyên liệu</label><input class="bk-input" name="name" maxlength="150" required value="<?=bakeryH($form['name'])?>"><div class="bk-form-grid"><div><label class="bk-label">Đơn vị tính</label><input class="bk-input" name="unit" maxlength="30" required value="<?=bakeryH($form['unit'])?>"></div><div><label class="bk-label">Tồn tối thiểu</label><input class="bk-input" type="number" min="0" step="0.001" name="minimum_stock" required value="<?=bakeryH($form['minimum_stock'])?>"></div></div><label class="bk-label">Ghi chú</label><textarea class="bk-textarea" name="note" maxlength="500"><?=bakeryH($form['note'])?></textarea><button class="bk-btn bk-btn-primary bk-btn-block"><?=$form['id']?'Lưu thay đổi':'Thêm nguyên liệu'?></button></form></section><section class="bk-table-wrap"><table class="bk-table"><thead><tr><th>Nguyên liệu</th><th>Đơn vị</th><th>Tồn hiện tại</th><th>Tối thiểu</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="bk-empty">Chưa có nguyên liệu.</div></td></tr><?php endif;?><?php foreach($rows as $r):$low=(float)$r['stock']<=(float)$r['minimum_stock'];?><tr><td><strong><?=bakeryH($r['name'])?></strong><div class="bk-muted"><?=bakeryH($r['note'])?></div></td><td><?=bakeryH($r['unit'])?></td><td class="<?=$low?'bk-low':'bk-ok'?>"><?=bakeryNumber($r['stock'])?></td><td><?=bakeryNumber($r['minimum_stock'])?></td><td><span class="bk-badge <?=(int)$r['is_active']?'green':''?>"><?=(int)$r['is_active']?'Đang dùng':'Ngừng dùng'?></span></td><td><div class="bk-actions"><a class="bk-btn bk-btn-secondary bk-btn-small" href="?edit=<?=(int)$r['id']?>">Sửa</a><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="bk-btn bk-btn-secondary bk-btn-small"><?=(int)$r['is_active']?'Ngừng':'Bật'?></button></form><form method="post" onsubmit="return confirm('Xóa nguyên liệu này? Chỉ nguyên liệu chưa có lịch sử nhập hoặc xuất kho mới xóa được.')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="bk-btn bk-btn-danger bk-btn-small">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></section></div></main></body></html>
